const chapters=[['Résumé exécutif','résumé-exécutif'],['Contexte et objectifs','contexte-et-objectifs'],['Données et périmètre','données-et-périmètre'],['Qualité et traçabilité','qualité-et-traçabilité'],['Méthodes et définitions','méthodes-et-définitions'],['Enquêtes et devenir des diplômés','enquêtes-et-devenir-des-diplômés'],['Parcours et suivi longitudinal','parcours-et-suivi-longitudinal'],['Modélisation exploratoire','modélisation-exploratoire'],['Résultats descriptifs','résultats-descriptifs'],['Indicateurs décisionnels','indicateurs-décisionnels'],['Recommandations de pilotage','recommandations-de-pilotage'],['Limites et précautions','limites-et-précautions'],['Reproductibilité et accès aux livrables','reproductibilité-et-accès-aux-livrables']];
const toc=document.getElementById('report-toc');if(toc)toc.innerHTML=chapters.map(([title,id],i)=>`<li><a href="rapport_final.html#${encodeURIComponent(id)}"><span>${String(i+1).padStart(2,'0')}</span>${title}<b>↗</b></a></li>`).join('');
const tabs=[...document.querySelectorAll('[data-tab]')];
function activate(tab){tabs.forEach(t=>{const active=t===tab;t.setAttribute('aria-selected',String(active));t.tabIndex=active?0:-1;document.getElementById('panel-'+t.dataset.tab).hidden=!active;});}
tabs.forEach((tab,i)=>{tab.addEventListener('click',()=>activate(tab));tab.addEventListener('keydown',event=>{let next;if(event.key==='ArrowRight')next=(i+1)%tabs.length;if(event.key==='ArrowLeft')next=(i+tabs.length-1)%tabs.length;if(event.key==='Home')next=0;if(event.key==='End')next=tabs.length-1;if(next!==undefined){event.preventDefault();activate(tabs[next]);tabs[next].focus();}});});
const menu=document.querySelector('.menu-toggle'),nav=document.getElementById('main-nav');if(menu&&nav){menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.classList.toggle('open',open);});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{menu.setAttribute('aria-expanded','false');nav.classList.remove('open');}));}
